// src/components/Questions/AddQuestion.js
import React, { useState } from 'react';
import './AddQuestion.css';
import { useNavigate } from 'react-router-dom';
import HomeIcon from '../Common/HomeIcon';
import { postQuestion } from '../../services/api';

function AddQuestion() {
  const [title, setTitle] = useState('');
  const [text, setText] = useState('');
  const [tags, setTags] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!title || !text) {
      alert("Completează toate câmpurile!");
      return;
    }

    const tagList = tags.split(',').map(tag => ({ tag: { name: tag.trim() } }));

    try {
      await postQuestion({
        title,
        text,
        user: { id: 1 },
        questionTags: tagList
      });

      alert("Întrebare adăugată!");
      navigate('/questions');
    } catch (err) {
      alert(err.message || 'Eroare la salvarea întrebării');
    }
  };

  return (
    <div className="add-question-container">
      <HomeIcon />
      <h2>Pune o întrebare</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Titlu întrebare"
          value={title}
          onChange={e => setTitle(e.target.value)}
        />
        <textarea
          placeholder="Conținut întrebare"
          value={text}
          onChange={e => setText(e.target.value)}
        />
        <input
          type="text"
          placeholder="Etichete separate prin virgulă (ex: java, spring)"
          value={tags}
          onChange={e => setTags(e.target.value)}
        />
        <button type="submit">Trimite întrebare</button>
      </form>
    </div>
  );
}

export default AddQuestion;
